from collections import deque
import sys

def main():
    data = sys.stdin.read().strip().splitlines()
    n = int(data[0])
    g = data[1:1+n]

    def idx(r, c): return r * n + c
    dr = (-1, 1, 0, 0)
    dc = (0, 0, -1, 1)

    visX = [False] * (n * n)   # 敌方连通块访问标记
    mark = [-1] * (n * n)      # 空位唯一气去重（按连通块id）
    capture = {}               # 空位索引 -> 累计可吃子数
    gid = 0

    for r in range(n):
        for c in range(n):
            if g[r][c] != 'x':
                continue
            id0 = idx(r, c)
            if visX[id0]:
                continue

            gid += 1
            q = deque()
            q.append((r, c))
            visX[id0] = True
            size = 0
            libCount = 0
            lastLib = -1

            while q:
                ur, uc = q.popleft()
                size += 1
                for k in range(4):
                    vr = ur + dr[k]
                    vc = uc + dc[k]
                    if not (0 <= vr < n and 0 <= vc < n):
                        continue
                    ch = g[vr][vc]
                    if ch == 'x':
                        nid = idx(vr, vc)
                        if not visX[nid]:
                            visX[nid] = True
                            q.append((vr, vc))
                    elif ch == '.':
                        e = idx(vr, vc)
                        if mark[e] != gid:
                            mark[e] = gid
                            libCount += 1
                            lastLib = e
                    # 'o' 忽略

            if libCount == 1:
                capture[lastLib] = capture.get(lastLib, 0) + size

    ans = []
    for e, cnt in capture.items():
        r, c = divmod(e, n)
        ans.append((r + 1, c + 1, cnt))
    ans.sort()

    print(len(ans))
    for a, b, cnt in ans:
        print(a, b, cnt)

if __name__ == "__main__":
    main()
